#!/usr/bin/env python3
from math import isqrt

def primes_upto(n):
    s=bytearray(b'\x01')*(n+1); s[:2]=b'\x00\x00'
    for r in range(2,isqrt(n)+1):
        if s[r]: s[r*r:n+1:r]=b'\x00'*(((n-r*r)//r)+1)
    return [i for i in range(2,n+1) if s[i]]

def H(p,r,m):
    return sum(pow(k,-r,m) for k in range(1,p))%m

def U_direct(p,m):
    u=1
    for k in range(1,p):
        x=p*pow(k,-1,m)%m
        u=u*(1+x)%m*(1+x)%m*(1+2*x)%m
    return u

def U10(p):
    m=p**10; h2,h4,h6,h8=(H(p,r,m) for r in (2,4,6,8))
    i2,i3,i4,i6=(pow(d,-1,m) for d in (2,3,4,6))
    return (1-5*p**2*h2-17*p**4*h4*i2+25*p**4*h2*h2*i2-65*p**6*h6*i3
            +85*p**6*h2*h4*i2-125*p**6*h2**3*i6-257*p**8*h8*i4)%m

def jet_direct(p,m):
    term=1; s0=s1=s2=s3=0
    for k in range(p):
        if k:
            term=term*(2*k-1)*(3*k-2)*(3*k-1)*pow(36*k**3,-1,m)%m
        s0=(s0+term)%m; s1=(s1+k*term)%m
        s2=(s2+k*(k-1)*term)%m
        s3=(s3+k*(k-1)*(k-2)*term)%m
    return (72*s3+108*s2-88*s1-8*s0)%m

def q6(p,pow_needed):
    m=p**(pow_needed+1); r=pow(6,p-1,m)
    assert (r-1)%p==0
    return ((r-1)//p)%(p**pow_needed)

def J13(p):
    m=p**13; q=q6(p,10); h2,h4,h6,h8=(H(p,r,m) for r in (2,4,6,8)); i3=pow(3,-1,m)
    return (-8*p**3+24*p**4*q-48*p**5*q**2+80*p**6*q**3-120*p**7*q**4+168*p**8*q**5-224*p**9*q**6+288*p**10*q**7-360*p**11*q**8+440*p**12*q**9
      +40*p**5*h2-120*p**6*q*h2+240*p**7*q**2*h2-400*p**8*q**3*h2+600*p**9*q**4*h2-840*p**10*q**5*h2+1120*p**11*q**6*h2
      +68*p**7*h4-204*p**8*q*h4+408*p**9*q**2*h4-680*p**10*q**3*h4+1020*p**11*q**4*h4
      -100*p**7*h2*h2+300*p**8*q*h2*h2-600*p**9*q**2*h2*h2+1000*p**10*q**3*h2*h2
      +520*i3*p**9*h6-520*p**10*q*h6+1040*p**11*q**2*h6-340*p**9*h2*h4+1020*p**10*q*h2*h4
      +500*i3*p**9*h2**3+514*p**11*h8)%m

def main():
    ps=[p for p in primes_upto(4999) if p%24 in (13,19)]
    fails=[]
    for p in ps:
        if U_direct(p,p**10)!=U10(p): fails.append((p,'U10'))
        if jet_direct(p,p**13)!=J13(p): fails.append((p,'J13'))
    counts={13:sum(p%24==13 for p in ps),19:sum(p%24==19 for p in ps)}
    print({'target_primes':len(ps),'counts':counts,'failures':fails})
    assert len(ps)==166 and counts=={13:83,19:83} and not fails

if __name__=='__main__': main()

#!/usr/bin/env python3
"""Exact regression for the finite 3F2 exact top factorization / p^6 jet.

The finite scan is falsification/regression only. The proof is the exact
binomial factor cancellation and the p^3 near-diagonal binomial congruence in
the companion note.
"""

from math import comb, isqrt


def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    d = 3
    while d <= isqrt(n):
        if n % d == 0:
            return False
        d += 2
    return True


def target_primes(bound: int = 5000):
    return [p for p in range(5, bound) if p % 24 in (13, 19) and is_prime(p)]


def coefficients(p: int, mod: int):
    out = [1]
    for k in range(p - 1):
        num = (2 * k + 1) * (3 * k + 1) * (3 * k + 2)
        den = 18 * (k + 1) ** 3
        out.append(out[-1] * (num % mod) * pow(den, -1, mod) % mod)
    return out


def derivatives_0_to_3(coeffs, x: int, mod: int):
    f0 = f1 = f2 = f3 = 0
    for a in reversed(coeffs):
        o0, o1, o2, o3 = f0, f1, f2, f3
        f3 = (o3 * x + 3 * o2) % mod
        f2 = (o2 * x + 2 * o1) % mod
        f1 = (o1 * x + o0) % mod
        f0 = (o0 * x + a) % mod
    return f0, f1, f2, f3


def fermat_q_mod_p2(a: int, p: int) -> int:
    # q_p(a) modulo p^2 requires a^(p-1) modulo p^3.
    return ((pow(a, p - 1, p ** 3) - 1) // p) % (p * p)


def main() -> None:
    primes = target_primes()
    classes = {13: 0, 19: 0}
    failures = []

    for p in primes:
        classes[p % 24] += 1

        # Direct p^3 checks on the near-diagonal binomial units.
        if comb(2 * p - 1, p - 1) % (p ** 3) != 1:
            failures.append((p, "binom2_not_1_mod_p3"))
        if comb(3 * p - 1, p - 1) % (p ** 3) != 1:
            failures.append((p, "binom3_not_1_mod_p3"))

        mod = p ** 6
        coeffs = coefficients(p, mod)
        x = pow(2, -1, mod)
        f0, f1, f2, f3 = derivatives_0_to_3(coeffs, x, mod)
        lhs = (9 * f3 + 27 * f2 - 44 * f1 - 8 * f0) % mod

        q6 = fermat_q_mod_p2(6, p)
        rhs = (-8 * p ** 3 + 24 * p ** 4 * q6 - 48 * p ** 5 * (q6 % p) ** 2) % mod
        if lhs != rhs:
            failures.append((p, "half_point_p6_jet", lhs, rhs, q6))

    print({
        "bound": 5000,
        "target_prime_count": len(primes),
        "class_counts": classes,
        "failure_count": len(failures),
        "failures": failures,
    })
    assert len(primes) == 166
    assert classes == {13: 83, 19: 83}
    assert not failures


if __name__ == "__main__":
    main()
